"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9301],{89301:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/four-knocks.png\\"\\n          title=\\"네 번의 노크\\"\\n          author=\\"케이시\\"\\n          publisher=\\"인플루엔셜\\"\\n          publishedDate=\\"2021-10-28\\"\\n          isbn=\\"9791191056136\\"\\n          rating=3.5\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n```알라딘 중고서점```에서 계산을 위해 카운터에 갔는데, 옆에 ```알라딘 직원들의 추천 도서```로 소개되어 있어서 무심코 같이 구매했다.  \\n<br>\\n사건 자체와 재미 요소는 좋으나, 어딘가 조금 가볍다.  \\n하지만 <mark>내사</mark>와 용의자들의 <mark>독백</mark>을 나눈 부분이 몰입감에 도움이 되었다.  \\n하지만 ```독백``` 부분은 다소 루즈해진다.  \\n<br>\\n등장인물들이 이름이 아닌 301호, 302호 등으로 표기된다는 점에서 삭막한 ```원룸촌```이라는 배경을 잘 살려주는 것 같다.  \\n인물 이름을 외우지 않아도 된다는 점이 마음에 들었다.  \\n<br>\\n반전으로 가는 길이 충분히 매끄럽지 못하고 억지스럽긴 하다.\\n"}')}}]);